    from collections import Counter
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    keys = [tuple(tuple(grid[r][c] for c in range(left, left + 3)) for r in range(1, 4)) for left in (2, 7, 12, 17)]
