    counts = Counter(key_colors)
    repeated = [color for color, count in counts.items() if count > 1]
    fill = repeated[0] if repeated else 3
    if not repeated:
        for r in range(5):
            for c in range(width):
                if out[r][c] == 8:
                    out[r][c] = 3
    for r in range(height - 2, height):
        out[r] = [fill] * width
    for top in (8, 13, 18, 23):
        for left in (2, 7, 12, 17):
            obj = tuple(tuple(grid[r][c] for c in range(left, left + 3)) for r in range(top, top + 3))
            if obj in keys:
                for r in range(top - 1, top + 4):
                    for c in range(left - 1, left + 4):
                        if out[r][c] == 8:
                            out[r][c] = 3
    return out
'''
